'use client';

import { useState } from 'react';

import { MotionNumber } from '@/components/core/motion-number';
import { WordRoll } from '@/components/core/word-roll';
import type { AutoplayStep } from '@/registry/ndeko/hooks/use-autoplay';
import { hold } from '@/registry/ndeko/lib/demonstration';
import { cn } from '@/registry/ndeko/lib/utils';

import { CategoryAxis, LABEL_ROOM_PX, type AxisLabel } from './_parts/axis';
import { ChartCard } from './_parts/chart-card';
import { DataTable, type DataRow } from './_parts/data-table';
import { walkSteps } from './_parts/demo';
import { formatCount } from './_parts/format';
import { PLOT_SURFACE } from './_parts/plot';
import { clamp, positionsTo, sumOf } from './_parts/scale';
import { useChartDemo } from './_parts/use-chart-demo';
import { usePlotWidth } from './_parts/use-plot-width';
import { useStepDrag } from './_parts/use-step-drag';

export type HistogramBin = {
  /** Where the bin starts and where it ends, in the unit of the measure. */
  from: number;
  to: number;
  /** How many readings fell in it. */
  count: number;
};

export type DotHistogramProps = {
  title: string;
  /** A short mark beside the title, such as "Illustrative" over sample data. */
  note?: string;
  /** The bins from the lowest to the highest, each as wide as the others. */
  bins: readonly HistogramBin[];
  /** How many readings one dot stands for. */
  perDot: number;
  /** The edge the target sits on: 0 is before the first bin, `bins.length` is after the last. */
  targetEdge: number;
  onTargetEdgeChange: (edge: number) => void;
  /** The unit of the measure, written after a figure: "ms". */
  unit: string;
  /** What is counted, in the plural: "requests". */
  noun: string;
  className?: string;
};

const DOT_PX = 10;

const DOT_GAP_PX = 2;

const DOT_PITCH_PX = DOT_PX + DOT_GAP_PX;

/** Room above the tallest column for the label of the target. */
const PIN_ROOM_PX = 28;

/** Columns change colour one after the other, starting from the one beside the pin. */
const STAGGER_MS = 30;

/** One label of the axis every this many edges: the first step that leaves each label its room, so the values stay round. */
const LABEL_STEPS = [4, 8];

const WIDEST_LABEL_STEP = 16;

const FALLBACK_WIDTH = 420;

function labelStepFor(binCount: number, plotWidth: number) {
  for (const step of LABEL_STEPS) {
    const gapCount = Math.floor(binCount / step);
    const labelCount = gapCount + 1;
    const room = plotWidth / labelCount;
    if (room >= LABEL_ROOM_PX) {
      return step;
    }
  }
  return WIDEST_LABEL_STEP;
}

function dotCountOf(bin: HistogramBin, perDot: number) {
  const dots = bin.count / perDot;
  return Math.round(dots);
}

function tallestOf(bins: readonly HistogramBin[], perDot: number) {
  let tallest = 1;
  for (const bin of bins) {
    const dots = dotCountOf(bin, perDot);
    tallest = Math.max(tallest, dots);
  }
  return tallest;
}

/** The value an edge sits on: the start of the bin after it, or the end of the last bin. */
function edgeValueOf(bins: readonly HistogramBin[], edge: number) {
  const bin = bins[edge];
  if (bin) {
    return bin.from;
  }
  const last = bins.at(-1);
  return last?.to ?? 0;
}

function countPast(bins: readonly HistogramBin[], edge: number) {
  const past = bins.slice(edge);
  const counts = past.map((bin) => bin.count);
  return sumOf(counts);
}

/** How many columns lie between a column and the pin, on whichever side of it the column is. */
function distanceFromPin(column: number, edge: number) {
  if (column >= edge) {
    return column - edge;
  }
  const lastBefore = edge - 1;
  return lastBefore - column;
}

function dotToneOf(isPastTarget: boolean) {
  if (isPastTarget) {
    return 'bg-destructive';
  }
  return 'bg-primary';
}

type DotColumnProps = {
  dotCount: number;
  isPastTarget: boolean;
  /** How many columns away from the pin this one is: the further, the later it changes colour. */
  distance: number;
};

function DotColumn({ dotCount, isPastTarget, distance }: DotColumnProps) {
  const dots = Array.from({ length: dotCount }, (_, index) => index);
  const delayMs = distance * STAGGER_MS;

  return (
    <span className='flex min-w-0 flex-1 flex-col-reverse items-center gap-0.5'>
      {dots.map((dot) => (
        <span
          key={dot}
          className={cn(
            'size-2.5 shrink-0 rounded-full transition-colors duration-200 ease-(--ease-out-strong)',
            dotToneOf(isPastTarget)
          )}
          style={{ transitionDelay: `${delayMs}ms` }}
        />
      ))}
    </span>
  );
}

function axisLabelsOf(
  bins: readonly HistogramBin[],
  unit: string,
  plotWidth: number
) {
  const edgeCount = bins.length + 1;
  const edges = Array.from({ length: edgeCount }, (_, edge) => edge);
  const step = labelStepFor(bins.length, plotWidth);
  const written = edges.filter((edge) => edge % step === 0);
  return written.map((edge): AxisLabel => {
    const edgeValue = edgeValueOf(bins, edge);
    const value = formatCount(edgeValue);
    const isLast = edge === bins.length;
    return {
      id: String(edge),
      text: labelTextOf(value, unit, isLast),
      ratio: edge / bins.length,
    };
  });
}

/** Only the last label carries the unit, so the axis is not a row of the same two letters. */
function labelTextOf(value: string, unit: string, isLast: boolean) {
  if (isLast) {
    return `${value}${unit}`;
  }
  return value;
}

function rangeTextOf(bin: HistogramBin, unit: string) {
  const from = formatCount(bin.from);
  const to = formatCount(bin.to);
  return `${from} to ${to}${unit}`;
}

function standingOf(isPastTarget: boolean) {
  if (isPastTarget) {
    return 'Slower than the target';
  }
  return 'Within the target';
}

export function DotHistogram({
  title,
  note,
  bins,
  perDot,
  targetEdge,
  onTargetEdgeChange,
  unit,
  noun,
  className,
}: DotHistogramProps) {
  const { plotRef, width } = usePlotWidth(FALLBACK_WIDTH);
  const binCount = Math.max(bins.length, 1);
  const edge = clamp(targetEdge, 0, bins.length);
  const drag = useStepDrag({
    count: bins.length + 1,
    index: edge,
    onIndexChange: onTargetEdgeChange,
    placement: 'edges',
  });
  const tallest = tallestOf(bins, perDot);
  const columnsHeight = tallest * DOT_PITCH_PX;
  const plotHeight = columnsHeight + PIN_ROOM_PX;
  const counts = bins.map((bin) => bin.count);
  const counted = sumOf(counts);
  const total = Math.max(counted, 1);
  const slowCount = countPast(bins, edge);
  const slowShare = slowCount / total;
  const slowPercent = Math.round(slowShare * 100);
  const edgeValue = edgeValueOf(bins, edge);
  const targetValue = formatCount(edgeValue);
  const targetText = `${targetValue}${unit}`;
  const sentence = `${slowPercent}% of ${noun} are slower than ${targetText}`;
  const pinRatio = edge / binCount;
  const pinShare = pinRatio * 100;

  const rows: DataRow[] = bins.map((bin, column) => ({
    id: String(bin.from),
    label: rangeTextOf(bin, unit),
    cells: [formatCount(bin.count), standingOf(column >= edge)],
  }));

  return (
    <ChartCard
      title={title}
      note={note}
      summary={`${sentence}. One dot is ${perDot} ${noun}.`}
      className={className}
    >
      <p className='flex flex-wrap items-baseline gap-x-1.5'>
        <MotionNumber
          value={slowPercent}
          suffix='%'
          className='text-2xl leading-8 font-semibold'
        />
        <span className='text-muted-foreground text-[13px]'>
          of {noun} are slower than{' '}
          <WordRoll
            text={targetText}
            value={edge}
            className='text-foreground font-medium tabular-nums'
          />
        </span>
      </p>
      <div className='flex flex-col'>
        <div
          ref={plotRef}
          role='slider'
          tabIndex={0}
          aria-label={`Target, in ${unit}`}
          aria-orientation='horizontal'
          aria-valuemin={0}
          aria-valuemax={bins.length}
          aria-valuenow={edge}
          aria-valuetext={sentence}
          className={cn(
            PLOT_SURFACE,
            'flex cursor-ew-resize items-end select-none'
          )}
          style={{ height: plotHeight }}
          {...drag.sliderProps}
        >
          {bins.map((bin, column) => (
            <DotColumn
              key={bin.from}
              dotCount={dotCountOf(bin, perDot)}
              isPastTarget={column >= edge}
              distance={distanceFromPin(column, edge)}
            />
          ))}
          <span
            aria-hidden='true'
            className='pointer-events-none absolute inset-y-0 left-0 w-0 transition-transform duration-150 ease-(--ease-out-strong)'
            style={{ transform: `translateX(${pinShare}cqw)` }}
          >
            <span className='bg-foreground absolute inset-y-0 left-0 w-0.5 -translate-x-1/2 rounded-full' />
            <span className='bg-foreground ring-card absolute -bottom-1.5 left-0 size-3 -translate-x-1/2 rounded-full ring-2' />
            <span
              className='bg-foreground text-background absolute top-0 left-0 flex h-5 w-max items-center rounded-md px-1.5 text-[11px] font-medium tabular-nums transition-transform duration-150 ease-(--ease-out-strong)'
              style={{ transform: `translateX(-${pinShare}%)` }}
            >
              {targetText}
            </span>
          </span>
        </div>
        <span aria-hidden='true' className='hairline-t border-border' />
        <CategoryAxis
          labels={axisLabelsOf(bins, unit, width)}
          className='mt-2'
        />
      </div>
      <p className='text-muted-foreground text-xs'>
        One dot is {perDot} {noun}. Drag the pin, or use the arrow keys, to move
        the target
      </p>
      <DataTable
        caption={title}
        columns={['Range', noun, 'Against the target']}
        rows={rows}
      />
    </ChartCard>
  );
}

const BIN_WIDTH_MS = 100;

const REQUEST_COUNTS = [
  20, 60, 140, 200, 220, 180, 140, 120, 100, 80, 60, 60, 40, 40, 20, 20,
];

const BINS: HistogramBin[] = REQUEST_COUNTS.map((count, index) => {
  const from = index * BIN_WIDTH_MS;
  const to = from + BIN_WIDTH_MS;
  return { from, to, count };
});

const RESTING_EDGE = 8;

const STRICT_EDGE = 5;

const LOOSE_EDGE = 12;

export default function Chart10() {
  const [targetEdge, setTargetEdge] = useState(RESTING_EDGE);

  function resetDemo() {
    setTargetEdge(RESTING_EDGE);
  }

  const toStrict = positionsTo(RESTING_EDGE, STRICT_EDGE);
  const toLoose = positionsTo(STRICT_EDGE, LOOSE_EDGE);
  const toResting = positionsTo(LOOSE_EDGE, RESTING_EDGE);
  const steps: AutoplayStep[] = [
    ...walkSteps(toStrict, setTargetEdge, { startAfter: 1500, stepMs: 260 }),
    ...walkSteps(toLoose, setTargetEdge, { startAfter: 1800, stepMs: 110 }),
    ...walkSteps(toResting, setTargetEdge, { startAfter: 1800, stepMs: 260 }),
    { after: 1400, run: hold },
  ];
  const { ref, stopOnKeyboardFocus } = useChartDemo(steps, {
    loopAfter: 1600,
    onReset: resetDemo,
  });

  return (
    <div
      ref={ref}
      onFocus={stopOnKeyboardFocus}
      className='flex min-h-[21.5rem] w-full max-w-[30rem]'
    >
      <DotHistogram
        title='Response time'
        note='Illustrative'
        bins={BINS}
        perDot={20}
        targetEdge={targetEdge}
        onTargetEdgeChange={setTargetEdge}
        unit='ms'
        noun='requests'
        className='w-full'
      />
    </div>
  );
}

import { cn } from '@/registry/ndeko/lib/utils';

import { yOf } from './path';
import { columnCenterOf, percentOf, type Scale } from './scale';

/** The least room one label of the category axis needs, text and breathing space. */
export const LABEL_ROOM_PX = 56;

type ValueAxisProps = {
  scale: Scale;
  height: number;
  format: (value: number) => string;
  className?: string;
};

/** The figures of the value axis, one per gridline, in a column beside the plot. */
export function ValueAxis({
  scale,
  height,
  format,
  className,
}: ValueAxisProps) {
  return (
    <div
      aria-hidden='true'
      className={cn('relative w-9 shrink-0', className)}
      style={{ height }}
    >
      {scale.ticks.map((tick) => (
        <span
          key={tick}
          className='text-muted-foreground absolute right-0 -translate-y-1/2 text-[11px] tabular-nums'
          style={{ top: yOf(tick, scale, height) }}
        >
          {format(tick)}
        </span>
      ))}
    </div>
  );
}

/** Zero is drawn stronger when values go below it, since bars start there. */
export function gridToneOf(tick: number, scale: Scale) {
  const isZero = tick === 0;
  const crossesZero = scale.min < 0;
  if (isZero && crossesZero) {
    return 'border-foreground/25';
  }
  return 'border-border';
}

type GridLinesProps = {
  scale: Scale;
  height: number;
};

export function GridLines({ scale, height }: GridLinesProps) {
  return (
    <div aria-hidden='true' className='pointer-events-none absolute inset-0'>
      {scale.ticks.map((tick) => (
        <span
          key={tick}
          className={cn(
            'hairline-t absolute inset-x-0',
            gridToneOf(tick, scale)
          )}
          style={{ top: yOf(tick, scale, height) }}
        />
      ))}
    </div>
  );
}

export type AxisLabel = {
  id: string;
  text: string;
  /** From 0 at the left edge of the plot to 1 at its right edge. */
  ratio: number;
  isStrong?: boolean;
};

/** Every how many positions a label is written, so the labels that are written never touch. */
export function labelStepOf(count: number, plotWidth: number) {
  const fitting = Math.floor(plotWidth / LABEL_ROOM_PX);
  const labelCount = Math.max(fitting, 1);
  const step = Math.ceil(count / labelCount);
  return Math.max(step, 1);
}

/** The labels kept when one in `step` is written, counted back from the last so the latest is always named. */
export function spacedLabelsOf(labels: readonly AxisLabel[], step: number) {
  const lastIndex = labels.length - 1;
  return labels.filter((_, index) => {
    const fromLast = lastIndex - index;
    return fromLast % step === 0;
  });
}

/**
 * One label per position, under the middle of its column, written as often as the room allows. The
 * one at `strongIndex`, such as today, is set stronger.
 */
export function positionLabelsOf(
  labels: readonly string[],
  plotWidth: number,
  strongIndex?: number
) {
  const all: AxisLabel[] = labels.map((text, index) => ({
    id: `${index}-${text}`,
    text,
    ratio: columnCenterOf(index, labels.length),
    isStrong: index === strongIndex,
  }));
  const step = labelStepOf(labels.length, plotWidth);
  return spacedLabelsOf(all, step);
}

function strongOf(isStrong: boolean | undefined) {
  if (isStrong) {
    return 'text-foreground font-medium';
  }
  return 'text-muted-foreground';
}

type LabelAlign = 'spread' | 'center';

/**
 * A spread label slides from its left edge to its right edge as it crosses the plot, like the
 * readout, so the first and the last never stick out of the piece. A centred label sits under its
 * mark, for the few wide columns of a bar chart.
 */
function labelStyleOf(
  label: AxisLabel,
  align: LabelAlign
): React.CSSProperties {
  const left = percentOf(label.ratio);
  if (align === 'center') {
    return { left, transform: 'translateX(-50%)' };
  }
  const shift = percentOf(-label.ratio);
  return { left, transform: `translateX(${shift})` };
}

type CategoryAxisProps = {
  labels: readonly AxisLabel[];
  align?: LabelAlign;
  className?: string;
};

export function CategoryAxis({
  labels,
  align = 'spread',
  className,
}: CategoryAxisProps) {
  return (
    <div aria-hidden='true' className={cn('relative h-4', className)}>
      {labels.map((label) => (
        <span
          key={label.id}
          className={cn(
            'absolute top-0 text-[11px] whitespace-nowrap tabular-nums',
            strongOf(label.isStrong)
          )}
          style={labelStyleOf(label, align)}
        >
          {label.text}
        </span>
      ))}
    </div>
  );
}

import { useId } from 'react';

import { cn } from '@/registry/ndeko/lib/utils';
import { Badge } from '@/registry/ndeko/ui/badge';

type ChartCardProps = {
  title: string;
  /** A short mark beside the title, such as "Illustrative" over sample data. */
  note?: string;
  /** One line that says what the chart shows, read by screen readers with the title. */
  summary: string;
  /** Controls that change what the chart draws: a period, a view. */
  actions?: React.ReactNode;
  className?: string;
  children: React.ReactNode;
};

/**
 * The surface every chart sits on. It is a query container, so a chart lays itself out by the
 * room it has, and it is positioned, so the hidden table of a chart never widens the page.
 */
export function ChartCard({
  title,
  note,
  summary,
  actions,
  className,
  children,
}: ChartCardProps) {
  const titleId = useId();
  const summaryId = useId();

  return (
    <section
      aria-labelledby={titleId}
      aria-describedby={summaryId}
      className={cn(
        'bg-card hairline-ring ring-border @container relative flex flex-col gap-4 rounded-xl p-4 shadow-[0_1px_2px_rgb(0_0_0/0.04)]',
        className
      )}
    >
      <header className='flex min-h-7 flex-wrap items-center justify-between gap-x-3 gap-y-2'>
        <div className='flex min-w-0 items-center gap-2'>
          <h3 id={titleId} className='text-sm font-medium text-balance'>
            {title}
          </h3>
          {note && <Badge variant='secondary'>{note}</Badge>}
        </div>
        {actions}
      </header>
      {children}
      <p id={summaryId} className='sr-only'>
        {summary}
      </p>
    </section>
  );
}

export type DataRow = {
  id: string;
  /** The heading of the row: a day, a category, a step. */
  label: string;
  cells: readonly string[];
};

type DataTableProps = {
  caption: string;
  /** The heading of the label column first, then one per cell. */
  columns: readonly string[];
  rows: readonly DataRow[];
};

/**
 * The numbers a chart draws, as a table for screen readers. It is taken out of the flow, so the
 * piece it sits in has to be positioned: a hidden box inside an area that scrolls sideways widens
 * the page otherwise.
 */
export function DataTable({ caption, columns, rows }: DataTableProps) {
  return (
    <table className='sr-only'>
      <caption>{caption}</caption>
      <thead>
        <tr>
          {columns.map((column) => (
            <th key={column} scope='col'>
              {column}
            </th>
          ))}
        </tr>
      </thead>
      <tbody>
        {rows.map((row) => (
          <tr key={row.id}>
            <th scope='row'>{row.label}</th>
            {row.cells.map((cell, index) => (
              <td key={index}>{cell}</td>
            ))}
          </tr>
        ))}
      </tbody>
    </table>
  );
}

import type { AutoplayStep } from '@/registry/ndeko/hooks/use-autoplay';
import { keyDelayOf } from '@/registry/ndeko/lib/demonstration';

type WalkOptions = {
  /** Milliseconds before the first position. */
  startAfter?: number;
  /** Milliseconds between two positions. */
  stepMs?: number;
};

/** One step per position, so a reading crosses a plot the way a pointer does. */
export function walkSteps<Position>(
  positions: readonly Position[],
  moveTo: (position: Position) => void,
  { startAfter = 700, stepMs = 240 }: WalkOptions = {}
): AutoplayStep[] {
  return positions.map((position, index) => {
    const after = keyDelayOf(index, startAfter, stepMs);
    return { after, run: () => moveTo(position) };
  });
}

/** What a demonstration points at lets go the moment a person takes over. */
export function whileDemonstrating<Value>(
  isDemonstrating: boolean,
  value: Value | null
) {
  if (isDemonstrating) {
    return value;
  }
  return null;
}

const LOCALE = 'en-US';

export const COUNT_FORMAT: Intl.NumberFormatOptions = {
  maximumFractionDigits: 0,
};

export const SIGNED_FORMAT: Intl.NumberFormatOptions = {
  maximumFractionDigits: 0,
  signDisplay: 'exceptZero',
};

export const USD_COMPACT_FORMAT: Intl.NumberFormatOptions = {
  style: 'currency',
  currency: 'USD',
  notation: 'compact',
  maximumFractionDigits: 1,
};

const COMPACT_FORMAT: Intl.NumberFormatOptions = {
  notation: 'compact',
  maximumFractionDigits: 1,
};

const COUNT = new Intl.NumberFormat(LOCALE, COUNT_FORMAT);

const SIGNED = new Intl.NumberFormat(LOCALE, SIGNED_FORMAT);

const COMPACT = new Intl.NumberFormat(LOCALE, COMPACT_FORMAT);

const USD_COMPACT = new Intl.NumberFormat(LOCALE, USD_COMPACT_FORMAT);

const DAY = new Intl.DateTimeFormat(LOCALE, {
  month: 'short',
  day: 'numeric',
  timeZone: 'UTC',
});

const MS_PER_DAY = 86_400_000;

export function formatCount(value: number) {
  return COUNT.format(value);
}

export function formatSigned(value: number) {
  return SIGNED.format(value);
}

export function formatCompact(value: number) {
  return COMPACT.format(value);
}

export function formatUsd(value: number) {
  return USD_COMPACT.format(value);
}

export function formatShare(share: number) {
  const percent = Math.round(share * 100);
  return `${percent}%`;
}

/** A start at zero has no percentage to grow from: it reads as no change. */
export function percentChangeOf(current: number, previous: number) {
  if (previous === 0) {
    return 0;
  }
  const difference = current - previous;
  const ratio = difference / Math.abs(previous);
  return Math.round(ratio * 100);
}

export function changeWordsOf(percent: number, reference: string) {
  if (percent === 0) {
    return `level with ${reference}`;
  }
  const size = Math.abs(percent);
  if (percent > 0) {
    return `up ${size}% on ${reference}`;
  }
  return `down ${size}% on ${reference}`;
}

export function nounOf(count: number, singular: string, plural: string) {
  if (count === 1) {
    return singular;
  }
  return plural;
}

/**
 * One label per day, or per `everyDays` days for a weekly series. Days are counted in UTC so the
 * server and the browser write the same label.
 */
export function dayLabelsOf(firstDay: string, count: number, everyDays = 1) {
  const start = Date.parse(`${firstDay}T00:00:00Z`);
  const stride = everyDays * MS_PER_DAY;
  return Array.from({ length: count }, (_, index) => {
    const elapsed = index * stride;
    return DAY.format(start + elapsed);
  });
}

import { columnCenterOf, lerp, ratioOf, type Domain } from './scale';

export type Point = {
  x: number;
  y: number;
};

/** Paths are drawn in a box this wide and stretched to the plot, so a change of width never redraws them. */
export const VIEW_WIDTH = 1000;

function commandOf(point: Point, index: number) {
  const x = point.x.toFixed(1);
  const y = point.y.toFixed(1);
  if (index === 0) {
    return `M${x} ${y}`;
  }
  return `L${x} ${y}`;
}

export function linePathOf(points: readonly Point[]) {
  const commands = points.map((point, index) => commandOf(point, index));
  return commands.join(' ');
}

/** The line closed down (or up) to a level, for the wash under a line. */
export function areaPathOf(points: readonly Point[], levelY: number) {
  if (points.length === 0) {
    return '';
  }
  const line = linePathOf(points);
  const lastIndex = points.length - 1;
  const firstX = points[0].x.toFixed(1);
  const lastX = points[lastIndex].x.toFixed(1);
  const level = levelY.toFixed(1);
  return `${line} L${lastX} ${level} L${firstX} ${level} Z`;
}

/** The surface between two lines that share their x positions, for a range around a line. */
export function bandPathOf(upper: readonly Point[], lower: readonly Point[]) {
  if (upper.length === 0) {
    return '';
  }
  const backwards = [...lower].reverse();
  const outline = [...upper, ...backwards];
  const line = linePathOf(outline);
  return `${line} Z`;
}

/** The pixel height of a value in a plot: the top of the domain is 0, its bottom is the plot height. */
export function yOf(value: number, domain: Domain, height: number) {
  const ratio = ratioOf(value, domain);
  const fromBottom = ratio * height;
  return height - fromBottom;
}

/** One point per value, each in the middle of its column. */
export function plotPointsOf(
  values: readonly number[],
  domain: Domain,
  height: number
): Point[] {
  return values.map((value, index) => {
    const share = columnCenterOf(index, values.length);
    const x = share * VIEW_WIDTH;
    const y = yOf(value, domain, height);
    return { x, y };
  });
}

/** How many of the pieces lie before a segment when they are shared out evenly. */
function piecesBefore(
  segment: number,
  segmentCount: number,
  pieceCount: number
) {
  const share = segment / segmentCount;
  return Math.floor(share * pieceCount);
}

/**
 * The same line through exactly `count` points: each segment is cut into equal parts, so two lines
 * of different lengths share one structure and one can glide into the other.
 */
export function densifyOf(points: readonly Point[], count: number): Point[] {
  const segmentCount = points.length - 1;
  const hasSegments = segmentCount >= 1;
  const hasRoom = count > points.length;
  if (!hasSegments || !hasRoom) {
    return [...points];
  }
  const pieceCount = count - 1;
  const dense: Point[] = [points[0]];
  for (let segment = 0; segment < segmentCount; segment += 1) {
    const from = points[segment];
    const to = points[segment + 1];
    const start = piecesBefore(segment, segmentCount, pieceCount);
    const end = piecesBefore(segment + 1, segmentCount, pieceCount);
    const parts = end - start;
    for (let part = 1; part <= parts; part += 1) {
      const amount = part / parts;
      const x = lerp(from.x, to.x, amount);
      const y = lerp(from.y, to.y, amount);
      dense.push({ x, y });
    }
  }
  return dense;
}

